design.custom_css:
/* Home hero (split). The photo sets the hero's height; the text is centred against it and fills its column. */
html body.zs-hv-split .elementor .zs-hero--home .zs-hero__media .zs-hero__img img { aspect-ratio: 16 / 10; }
@media (min-width: 901px) { html body.zs-hv-split .elementor .zs-hero--home .zs-hero__media .zs-hero__img img { aspect-ratio: 16 / 11; } }
body.zs-hv-split .zs-hero--home.zs-hero--img > .e-con-inner { align-items: center; }
body.zs-hv-split .e-con.zs-hero--home .e-con.zs-hero__text { align-self: center; justify-content: center; --justify-content: center; }
@media (min-width: 768px) {
  body.zs-hv-split .e-con.zs-hero--home { --padding-top: clamp(28px, 1rem + 1.6vw, 52px); --padding-bottom: clamp(32px, 1.2rem + 1.8vw, 60px); }
}
@media (min-width: 768px) and (max-width: 900px) {
  body.zs-hv-split .zs-hero--home.zs-hero--img > .e-con-inner { row-gap: 24px; }
}
@media (min-width: 901px) {
  html body.zs-hv-split .zs-hero--home.zs-hero--img > .e-con-inner { column-gap: clamp(32px, 4vw, 64px); }
  body.zs-hv-split .e-con.zs-hero--home .e-con.zs-hero__text { --row-gap: 24px; }
  body.zs-hv-split .zs-hero--home .zs-hero__title .elementor-heading-title { font-size: clamp(2.9rem, 1.6rem + 2.7vw, 4.4rem); line-height: 1.02; letter-spacing: -.015em; }
  body.zs-hv-split .zs-hero--home .zs-hero__lead { font-size: clamp(1.2rem, 1rem + .45vw, 1.4rem); max-width: none; }
  body.zs-hv-split .zs-hero--home .zs-hero__points .zs-checks { display: flex; flex-wrap: wrap; gap: 10px 28px; margin-top: 4px; }
}
@media (max-width: 767px) {
  body.zs-hv-split .e-con.zs-hero--home { --padding-bottom: 24px; }
  body.zs-hv-split .zs-hero--home .e-con.zs-hero__media { overflow: hidden; border-radius: var(--r-lg); }
  body.zs-hv-split .zs-hero--home .zs-hero__media :is(.elementor-widget-image, .elementor-widget-container) { height: 100%; }
}
/* Brand wordmark. No logo artwork exists: the only file the client supplied is a 97x28 px raster of the
   business name typed in a generic condensed italic, which cannot be shown at header size without blurring.
   The header therefore carries the name set in the site's own heading face, matching the footer wordmark. */
html body .zs-brand.zs-brand__name :is(.elementor-heading-title, a) {
  font-family: var(--f-head); font-weight: 800; font-size: 1.85rem; line-height: 1;
  letter-spacing: -.02em; color: var(--c-ink); text-decoration: none;
}
html body .zs-brand.zs-brand__name :is(.elementor-heading-title, a):hover { color: var(--c-primary); }
@media (min-width: 768px) and (max-width: 1024px) { html body .zs-brand.zs-brand__name :is(.elementor-heading-title, a) { font-size: 1.6rem; } }
@media (max-width: 767px) { html body .zs-brand.zs-brand__name :is(.elementor-heading-title, a) { font-size: 1.35rem; } }

/* Inner-page heroes (service pages + the hub) carry the page's own photograph, so they need the two things
   the home hero already has: a gutter between the photo and the text, and the text centred against the
   photo instead of stacked at the top of an equal-height column. Measured at 1440: the columns were both
   176-568 px tall, the text content filled only the top 215 px of its column, and the column gap was 0, so
   the lead ran flush into the edge of the photo. */
@media (min-width: 901px) {
  html body.zs-hv-split .zs-hero--page.zs-hero--img > .e-con-inner { column-gap: clamp(32px, 4vw, 64px); align-items: center; }
  body.zs-hv-split .e-con.zs-hero--page.zs-hero--img .e-con.zs-hero__text { align-self: center; justify-content: center; --justify-content: center; --row-gap: 18px; }
  body.zs-hv-split .zs-hero--page.zs-hero--img .zs-hero__lead { max-width: 56ch; }
}
